package com.valor.auth;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="otp_verifications") public class OtpVerification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") User user; @Column(nullable=false,length=20) String phone; @Column(name="otp_hash",nullable=false,length=255) String otpHash; @Column(name="attempts_remaining",nullable=false) short attemptsRemaining=3; @Column(name="max_attempts",nullable=false) short maxAttempts=3; @Column(name="expires_at",nullable=false) LocalDateTime expiresAt; @Column(name="locked_until") LocalDateTime lockedUntil; @Column(name="verified_at") LocalDateTime verifiedAt; @Column(name="created_at",nullable=false) LocalDateTime createdAt; @PrePersist void p(){createdAt=LocalDateTime.now();} public void setPhone(String v){phone=v;} public String getPhone(){return phone;} public void setOtpHash(String v){otpHash=v;} public String getOtpHash(){return otpHash;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public LocalDateTime getExpiresAt(){return expiresAt;} public short getAttemptsRemaining(){return attemptsRemaining;} public void setAttemptsRemaining(short v){attemptsRemaining=v;} public void setUser(User u){user=u;} public void setVerifiedAt(LocalDateTime v){verifiedAt=v;} public LocalDateTime getVerifiedAt(){return verifiedAt;} public LocalDateTime getLockedUntil(){return lockedUntil;} public void setLockedUntil(LocalDateTime v){lockedUntil=v;}}
